-- org.tg_locations_checks: A location's latitude is between -90 and 90, longitude between -180 and 180, time zone an IANA name known to the database, and operating hours an object of weekdays (mon to sun) each either {closed: true} or {open, close} as HH:MM with open before close (CR-070, FR-ADM-ORG-02); refused with constraints ck_locations_latitude_range, ck_locations_longitude_range, ck_locations_time_zone and ck_locations_operating_hours.
create or replace function org.tg_locations_checks() returns trigger
language plpgsql as $fn$
declare
    day_key text;
    day_value jsonb;
begin
    if new.latitude is not null and (new.latitude < -90 or new.latitude > 90) then
        raise exception 'latitude of location % is outside -90 to 90', new.id using errcode = '23514', constraint = 'ck_locations_latitude_range';
    end if;
    if new.longitude is not null and (new.longitude < -180 or new.longitude > 180) then
        raise exception 'longitude of location % is outside -180 to 180', new.id using errcode = '23514', constraint = 'ck_locations_longitude_range';
    end if;
    if not exists (select 1 from pg_catalog.pg_timezone_names n where n.name = new.time_zone) then
        raise exception 'time zone % of location % is not an IANA name', new.time_zone, new.id using errcode = '23514', constraint = 'ck_locations_time_zone';
    end if;
    if new.operating_hours is not null then
        if jsonb_typeof(new.operating_hours) <> 'object' then
            raise exception 'operating hours of location % are not an object', new.id using errcode = '23514', constraint = 'ck_locations_operating_hours';
        end if;
        for day_key, day_value in select * from jsonb_each(new.operating_hours) loop
            if day_key not in ('mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun') or jsonb_typeof(day_value) <> 'object' then
                raise exception 'operating hours of location % hold an unknown day %', new.id, day_key using errcode = '23514', constraint = 'ck_locations_operating_hours';
            end if;
            if day_value = '{"closed": true}'::jsonb then
                continue;
            end if;
            if not (day_value ?& array['open', 'close']) or (select count(*) from jsonb_object_keys(day_value)) <> 2
               or coalesce(day_value ->> 'open', '') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
               or coalesce(day_value ->> 'close', '') !~ '^([01][0-9]|2[0-3]):[0-5][0-9]$'
               or (day_value ->> 'open') >= (day_value ->> 'close') then
                raise exception 'operating hours of location % for % are not open before close', new.id, day_key using errcode = '23514', constraint = 'ck_locations_operating_hours';
            end if;
        end loop;
    end if;
    return new;
end
$fn$;
create or replace trigger tg_locations_checks before insert or update on org.locations
    for each row execute function org.tg_locations_checks();
